const key = ["nodejs", "util", "inspect", "custom"].join(".");
class Circle {
  constructor(radius) {
    this.radius = radius;
  }
  [Symbol.for(key)](depth, options, inspect) {
    return "Circle<" + inspect(this.radius, options) + " at depth " + depth + ">";
  }
}
exports.make = radius => new Circle(radius);
